import requests, time

response = requests.post(
    f"https://api.stability.ai/v2beta/audio/stable-audio/text-to-audio",
    headers={"authorization": f"Bearer sk-MYAPIKEY", "accept": "audio/*"},
    files={"none": ""},
    data={
        "prompt": "A cinematic orchestral piece with sweeping strings and dramatic brass.",
        "output_format": "mp3",
        "duration": 30,
    },
)

if response.status_code != 202:
    raise Exception(str(response.json()))

generation_id = response.json()["id"]

while True:
    result = requests.get(
        f"https://api.stability.ai/v2beta/audio/results/{generation_id}",
        headers={"authorization": f"Bearer sk-MYAPIKEY", "accept": "audio/*"},
    )
    if result.status_code == 202:
        print("Generation in-progress, retrying in 10 seconds...")
        time.sleep(10)
    elif result.status_code == 200:
        with open("./output.mp3", "wb") as f:
            f.write(result.content)
        break
    else:
        raise Exception(str(result.json()))

import fs from "node:fs";
import axios from "axios";
import FormData from "form-data";

const payload = {
  prompt: "A cinematic orchestral piece with sweeping strings and dramatic brass.",
  output_format: "mp3",
  duration: 30,
};

const response = await axios.postForm(
  `https://api.stability.ai/v2beta/audio/stable-audio/text-to-audio`,
  axios.toFormData(payload, new FormData()),
  {
    validateStatus: undefined,
    headers: { Authorization: `Bearer sk-MYAPIKEY`, Accept: "audio/*" },
  }
);

if (response.status !== 202) {
  throw new Error(`${response.status}: ${JSON.stringify(response.data)}`);
}

const { id: generationID } = response.data;

while (true) {
  const result = await axios.request({
    url: `https://api.stability.ai/v2beta/audio/results/${generationID}`,
    method: "GET",
    validateStatus: undefined,
    responseType: "arraybuffer",
    headers: { Authorization: `Bearer sk-MYAPIKEY`, Accept: "audio/*" },
  });

  if (result.status === 202) {
    console.log("Generation in-progress, retrying in 10 seconds...");
    await new Promise((resolve) => setTimeout(resolve, 10_000));
  } else if (result.status === 200) {
    fs.writeFileSync("./output.mp3", Buffer.from(result.data));
    break;
  } else {
    throw new Error(`${result.status}: ${result.data.toString()}`);
  }
}
